-- V17: the school Jelmágia (user's Hungarian text "Jelmágia", Part 14, approved 2026-10-17) and its first five mosaics, the varázskörök.
--   1. schools get an optional description (the lore of the school, shown on the page).
--   2. new school Jelmágia (fok 0 to 5) with its description.
--   3. the constraints of the mosaics table learn the five Jelmágia groups (subgroups) and the cost patterns perChoice and wrapper.
--   4. the five varázskörök: Bebörtönöző, Kirekesztő, Körbezáró, Védő, Végrehajtó.
ALTER TABLE schools ADD COLUMN description text;

INSERT INTO schools (id, name, has_tiers, description) VALUES ('jelmagia', 'Jelmágia', true, 'A világegyetem törvényszerűségeit nem csak szavakkal, hanem bizonyos különös vonalvezetésű jelekkel is meg lehet fogalmazni. Ezek a jelek képesek arra, hogy rabul ejtsék a mágikus energiákat, hogy átalakítsák, kisugározzák őket, akár a varázsló elméje. Általában nem többek, mint egyszerű végrehajtók, ám némelyikük a varázsló segítőjeként is közreműködik a varázslatok során, akár holmi egyszerű inas. A Jelmágia nagymesterei szinte minden már megismert mágikus hatást képesek rajzolatok formájában leírni.

A mágia ezen formájának valaha élt legnagyobb ismerőjéről, Moress Nobren mágusról az a legenda terjedt el, hogy egy alkalommal fél esztendős munkával egy egész hatalmas terem padlóját, falait és mennyezetét teleróva olyan mágikus jelrendszert alkotott, amely önálló gondolkodásra is képes volt. Egyetlen kötetbe összefoglalt életművéből, a Magica Graphicából idézünk:

A jelek mágikus formulák, a mágikus energia anyagba rögzített megnyilvánulásai. Meghatározó tulajdonságuk nem az anyag, amelyre írják őket, hanem a forma, a rajzolat vonalvezetése. A jelek tehát, bár nem bírnak anyagi minőséggel, mégis az anyag egy változatát jelentik, hiszen a forma, a külalak egyedül az Anyagi Világban meghatározó attribútum…

… Az eltérő – legalábbis az eltérőnek tekinthető – formák, így rajzolatok száma végtelen, végtelen tehát a Jelmágia jeleinek száma is. Ezzel együtt végtelen az így megidézhető mágikus módszerek és hatások sokasága is.

…A rajzolatok uralmat adnak a Világegyetem felett – nem különben és nem hitványabbak a mágikus igéknél és holmiknál. Talán csak annyiban különböznek, hogy bizonyos mágikus operációkhoz már elfeledtük a szavakat, míg a jelek reánk maradtak az elődöktől. Kutatjuk tartamukat, igyekszünk szétboncolni őket, hogy beléjük lássunk, egészen a vázat adó csontokig, akár a gyógyító teszi az emberi testtel. Állítom, semmit sem tudunk még alapvető titkairól…

…A mágikus szempontból tökéletes rajzolatot a varázsló csak transzban képes megalkotni. Mivelhogy a Jelmágia nem pusztán rajzolatból áll, hanem abból a transzban végrehajtott műveletből is, amelynek során a varázsló lelkének lenyomatát, egy lényéből kipattanó szikrát is elhelyez a vonalak között.
Ez az a parányi szikra, amelytől az életre kél …

A jelmágia a mágikus tartamú rajzolatokat 5 csoportba sorolja: varázskörök, varázsjelek, szimbólumok, bélyegek, pentagrammák.

Fő szabályok
Minden rajzolat elkészítéséhez szükséges a transz, ami tíz perces meditációt és 1 pszi pont felhasználását igényli.
Szimbólummágia 2. fok szükséges a felrajzolásukhoz, illetve egyes esetekben adott magasmágia ismerete.
Minden rajzolat elveszíti mágikus tartalmát, ha vonalai megsérülnek.
A jelmágiára – kevés kivétellel – nem alkalmazható Időmágia, Térmágia és Szimpatikus mágia!');

ALTER TABLE mosaics DROP CONSTRAINT mosaics_subgroup_chk;
ALTER TABLE mosaics ADD CONSTRAINT mosaics_subgroup_chk CHECK (
    (school = 'anyagi' AND subgroup IN ('elemi', 'termeszetes'))
    OR (school = 'jelmagia' AND subgroup IN ('varazskorok', 'varazsjelek', 'szimbolumok', 'belyegek', 'pentagrammak'))
    OR (school NOT IN ('anyagi', 'jelmagia') AND subgroup IS NULL));

ALTER TABLE mosaics DROP CONSTRAINT mosaics_cost_pattern_chk;
ALTER TABLE mosaics ADD CONSTRAINT mosaics_cost_pattern_chk CHECK (
    cost_pattern IN ('flat', 'perMass', 'compositionPerMass', 'compositionGrid', 'lookup', 'perChoice', 'wrapper', 'undefined'));

INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazskor-bebortonozo', 'Bebörtönöző varázskör', 'jelmagia', 'varazskorok', 2, 'complete', 'perChoice', 'Part 14', '{"id": "jel-varazskor-bebortonozo", "name": "Bebörtönöző varázskör", "school": "jelmagia", "subgroup": "varazskorok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 25}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": null, "step": null, "infinite": true}, "cost": {"pattern": "perChoice", "input": "creatureClass", "mpByValue": {"felhalott": 20, "kisertet": 30, "demon": 40, "demonur": 70}}, "inputs": [{"id": "creatureClass", "label": "Lény hovatartozása", "type": "choice", "values": ["felhalott", "kisertet", "demon", "demonur"], "labels": {"felhalott": "Félhalottak", "kisertet": "Kísértetek és lelkek", "demon": "Alsó- és közrendű démonok", "demonur": "Démonurak és -hercegek"}}], "effect": "A bebörtönzésre használatos varázskör a bezárt lényt megakadályozza abban, hogy a belső körívből kitörjön.\n\nA bebörtönző varázskörök bizonyos lényeknek a belső körbe történő bezárására használatosak. Ez azt jelenti, hogy az adott lény képtelen átlépni a belső kör vonalát, és kijutni azon belülről. Egyébként minden szempontból hasonlóak a Kirekesztő Varázskörökhöz, az Mp igényük meghatározásában az ott említett táblázat irányadó.\n\nA varázskör az összes jelmágikus rajzolathoz hasonlóan addig fejti ki hatását, amíg vonalai sértetlenek. Maga a kiszemelt lény képtelen arra, hogy megtörje a varázskör vonalait. Még mágikus úton sem: ez irányú varázslatai létre sem jönnek. Természetesen szép szóval, fenyegetéssel, Asztrál vagy Mentál mágiával rávehet erre bárkit.\n\nLény hovatartozása – Mp:\nfélhalottak – 20\nkísértetek és lelkek – 30\nalsó- és közrendű démonok – 40\ndémonurak és -hercegek – 70", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazskor-kirekeszto', 'Kirekesztő varázskör', 'jelmagia', 'varazskorok', 2, 'complete', 'perChoice', 'Part 14', '{"id": "jel-varazskor-kirekeszto", "name": "Kirekesztő varázskör", "school": "jelmagia", "subgroup": "varazskorok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 25}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": null, "step": null, "infinite": true}, "cost": {"pattern": "perChoice", "input": "creatureClass", "mpByValue": {"felhalott": 20, "kisertet": 30, "demon": 40, "demonur": 70}}, "inputs": [{"id": "creatureClass", "label": "Lény hovatartozása", "type": "choice", "values": ["felhalott", "kisertet", "demon", "demonur"], "labels": {"felhalott": "Félhalottak", "kisertet": "Kísértetek és lelkek", "demon": "Alsó- és közrendű démonok", "demonur": "Démonurak és -hercegek"}}], "effect": "A kirekesztő varázskör lehetetlenné teszi, hogy a teremtmény, aki ellen alkották, a külső körív vonalát átlépje.\n\nA kirekesztő varázskörök arra használatosak, hogy bizonyos nem természeti eredetű lényeket visszatartsanak a külső köríven belüli területekről. Ez úgy történik, hogy az adott lény a mágikus hatások miatt képtelen átlépni a körívet, ám varázslatai átjutnak azon. Az, hogy egy efféle varázskör mennyi Mp-be kerül, attól függ, hogy milyen lény távoltartására készült. Erről a következő táblázat tudósít.\n\nLény hovatartozása – Mp:\nfélhalottak – 20\nkísértetek és lelkek – 30\nalsó- és közrendű démonok – 40\ndémonurak és -hercegek – 70\n\nA kirekesztő varázskör az összes jelmágikus rajzolathoz hasonlóan addig fejti ki hatását, amíg vonalai sértetlenek. Maga a kiszemelt lény képtelen arra, hogy megtörje a varázskör vonalait. Még mágikus úton sem: ez irányú varázslatai létre sem jönnek. Természetesen szép szóval, fenyegetéssel, Asztrál vagy Mentál mágiával rávehet erre bárkit.", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazskor-korbezaro', 'Körbezáró varázskör', 'jelmagia', 'varazskorok', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazskor-korbezaro", "name": "Körbezáró varázskör", "school": "jelmagia", "subgroup": "varazskorok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 20}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 3}, "inputs": [{"id": "effectType", "label": "Hatás", "type": "choice", "values": ["ostuz", "osviz", "osfold", "oslevego", "elemiero", "termeszetesanyagi", "asztral", "ter", "ido", "mental", "szimpatikus"], "labels": {"ostuz": "Ős tűz", "osviz": "Ős víz", "osfold": "Ős föld", "oslevego": "Ős levegő", "elemiero": "Elemi erő", "termeszetesanyagi": "Természetes anyagi mágia", "asztral": "Asztrálmágia", "ter": "Térmágia", "ido": "Időmágia", "mental": "Mentálmágia", "szimpatikus": "Szimpatikus mágia"}, "requires": {"ostuz": [{"school": "anyagi", "tier": 2}], "osviz": [{"school": "anyagi", "tier": 2}], "osfold": [{"school": "anyagi", "tier": 2}], "oslevego": [{"school": "anyagi", "tier": 2}], "elemiero": [{"school": "anyagi", "tier": 2}], "termeszetesanyagi": [{"school": "anyagi", "tier": 2}], "asztral": [{"school": "asztral", "tier": 2}], "ter": [{"school": "ter", "tier": 2}], "ido": [{"school": "ido", "tier": 2}], "mental": [{"school": "mental", "tier": 2}], "szimpatikus": [{"school": "szimpatikus", "tier": 2}]}}], "effect": "A körbezáró varázskör a hatást éppen hogy a belső kör vonalán belülre korlátozza.\n\nA körbezáró varázskörök a védő varázskörökhöz hasonlóan működnek, azzal a különbséggel, hogy a hatást, ami ellen készítették őket, nem a külső körön kívülre korlátozzák, hanem bezárják a belső körön belülre – megakadályozva, hogy azon túl is érvényesüljön. A hatásból annyi jut ki, amennyi a védő varázskörnél említett módon ott belülre kerülhet. Azaz: a kijutó E egyenlő a hatás E-je mínusz a varázskör E-je.\n\nKörnyezeti hatások erőssége minden esetben 15 E-nek számít.\n\nArról, hogy milyen típusú körbezáró varázskörök léteznek és ezek 1 E-s erősítéséhez mennyi Mp szükséges, a Védő varázsköröknél ismertetett táblázat tudósít.\n\nHatás – Magasmágia – Mp/E:\nŐstűz, Ősvíz, Ősföld, Őslevegő – Anyagi mágia 2. fok – 3\nElemi erő – Anyagi mágia 2. fok – 3\nTermészetes anyagi mágia – Anyagi mágia 2. fok – 3\nAsztrálmágia – Asztrálmágia 2. fok – 3\nTérmágia – Térmágia 2. fok – 3\nIdőmágia – Időmágia 2. fok – 3\nMentálmágia – Mentálmágia 2. fok – 3\nSzimpatikus mágia – Szimpatikus mágia 2. fok – 3\n\nA varázsköröknek nem kell a teljes varázslat E-jével megbirkóznia, irányulhatnak annak egyetlen mozaikja ellen is. Ilyenkor a körön kívül csak az adott mozaik nem érvényesül, a varázslatba foglalt többi igen.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazskor-vedo', 'Védő varázskör', 'jelmagia', 'varazskorok', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazskor-vedo", "name": "Védő varázskör", "school": "jelmagia", "subgroup": "varazskorok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 20}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 3}, "inputs": [{"id": "effectType", "label": "Hatás", "type": "choice", "values": ["ostuz", "osviz", "osfold", "oslevego", "elemiero", "termeszetesanyagi", "asztral", "ter", "ido", "mental", "szimpatikus"], "labels": {"ostuz": "Ős tűz", "osviz": "Ős víz", "osfold": "Ős föld", "oslevego": "Ős levegő", "elemiero": "Elemi erő", "termeszetesanyagi": "Természetes anyagi mágia", "asztral": "Asztrálmágia", "ter": "Térmágia", "ido": "Időmágia", "mental": "Mentálmágia", "szimpatikus": "Szimpatikus mágia"}, "requires": {"ostuz": [{"school": "anyagi", "tier": 2}], "osviz": [{"school": "anyagi", "tier": 2}], "osfold": [{"school": "anyagi", "tier": 2}], "oslevego": [{"school": "anyagi", "tier": 2}], "elemiero": [{"school": "anyagi", "tier": 2}], "termeszetesanyagi": [{"school": "anyagi", "tier": 2}], "asztral": [{"school": "asztral", "tier": 2}], "ter": [{"school": "ter", "tier": 2}], "ido": [{"school": "ido", "tier": 2}], "mental": [{"school": "mental", "tier": 2}], "szimpatikus": [{"school": "szimpatikus", "tier": 2}]}}], "effect": "A védő varázskör bizonyos mágikus hatásoknak vet gátat, azaz a megjelölt hatás nem juthat be a külső köríven belülre.\n\nA védő varázskörök arra használatosak, hogy egy adott mágikus hatástól megvédjék a varázskör külső körén belül eső területet (csak varázslatokat gyengítenek).\n\nMágikus hatás esetén: a védett területen, ha a varázskör E-je nagyobb a mágikus hatás E-jénél, a hatás nem érvényesül. Ha a varázskör E-je kisebb, akkor a hatásból csak annyi jut át a védő varázskörön, amennyivel E-je több, mint a varázsköré (bejutott E = hatás E – varázskör E). Ebben az esetben a védett területen belül az adott hatás csak bejutott E-jének függvényében érvényesül.\n\nKörnyezeti hatások erőssége minden esetben 15 E-nek számít.\n\nArról, hogy milyen típusú varázskörök léteznek, és ezek 1 E-s erősítéséhez mennyi Mp szükséges, a következő táblázat tudósít:\n\nHatás – Magasmágia – Mp/E:\nŐstűz, Ősvíz, Ősföld, Őslevegő – Anyagi mágia 2. fok – 3\nElemi erő – Anyagi mágia 2. fok – 3\nTermészetes anyagi mágia – Anyagi mágia 2. fok – 3\nAsztrálmágia – Asztrálmágia 2. fok – 3\nTérmágia – Térmágia 2. fok – 3\nIdőmágia – Időmágia 2. fok – 3\nMentálmágia – Mentálmágia 2. fok – 3\nSzimpatikus mágia – Szimpatikus mágia 2. fok – 3\n\nA varázsköröknek nem kell a teljes varázslat E-jével megbirkóznia, irányulhatnak annak egyetlen mozaikja ellen is. Ilyenkor a körön belül csak az adott mozaik nem érvényesül, a varázslatba foglalt többi igen.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazskor-vegrehajto', 'Végrehajtó varázskör', 'jelmagia', 'varazskorok', 3, 'complete', 'wrapper', 'Part 14', '{"id": "jel-varazskor-vegrehajto", "name": "Végrehajtó varázskör", "school": "jelmagia", "subgroup": "varazskorok", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 30}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "wrapper", "baseMp": 40, "factor": 1}, "inputs": [], "effect": "A végrehajtó varázskörbe bármilyen mozaikokból felépített varázslat beleírható, és csak akkor aktivizálódik, ha valaki a varázskörbe lép. Fontos megkötés, hogy a varázslat – bármekkora is legyen eredeti hatóterülete – csak a varázskör belső körívén belül eső területre, illetve az ott tartózkodókra hat, ott azonban válogatás nélkül mindenkire.\n\nA varázskör felrajzolása 40 mp, plusz még annyi, amennyibe a beleírt varázslat kerül. A beleírt varázslatot csak egyszer képes végrehajtani, de a kimerült varázskör annyi mannapontért, amennyi a beleírt varázslat mp igénye, újra tölthető. Ha vonalai megtörnek, a varázslat kiszabadul és kifejti hatását, de a rajzolat többé nem használható.", "source": "Part 14"}'::jsonb);
